<?php
namespace Tivoli\Service;
use Tivoli\Repository\ChargeAccounting as C;
use Tivoli\Domain\Stay\StayRules as R;
use Tivoli\Security\PermissionDenied;
use RuntimeException;

/** Source-linked charge requests; approval and compensating journal commit with required audit. */
final class GuestChargeCorrectionService
{
    public function __construct(private readonly AccessService $access,private readonly ?string $clock=null){}
    private function now():string{return $this->clock??gmdate('Y-m-d H:i:s');}
    public function owner(int $actor):bool{return (new FinanceService($this->access,$this->now()))->canPostLate($actor);}
    public function permit(int $actor):void{$this->access->requirePrivilege($actor,'bookings.manage');if(!(new FinanceService($this->access))->installed())throw new RuntimeException('Finance setup is required.');}
    private function hash(mixed $v):string{return hash('sha256',json_encode($v,JSON_THROW_ON_ERROR));}
    private function id(string $v):int{if(!preg_match('/^[1-9][0-9]{0,17}$/D',$v))throw new RuntimeException('Choose a valid source.');return (int)$v;}
    public function source(int $actor,int $booking,string $type,int $source):array{
        $this->permit($actor);$r=$this->access->repo;$b=$r->run('SELECT b.*,r.name room_name FROM bookings b JOIN rooms r ON r.id=b.room_id WHERE b.id=?',[$booking])->fetch();if(!$b)throw new RuntimeException('Guest stay not found.');$stay=new StayService($this->access,$this->now());$bill=$stay->bill($b,$this->now());$frozen=$r->run('SELECT * FROM stay_departures WHERE booking_id=?',[$booking])->fetch();$blockers=[];
        if($bill['legacy_unknown']||$bill['provisional'])$blockers[]='Finalize the evidenced stay bill before correcting charges.';
        if($b['status']!=='active'&&!$frozen)$blockers[]='This historical stay has no verified final bill. Do not guess its charges.';
        if($type==='room'){
            if($source!==$booking)throw new RuntimeException('Room charge does not belong to this stay.');if(!$frozen)$blockers[]='Room charges are finalized at departure. Use a finalized bill for a room-charge correction.';
            $row=$frozen?:$b;$base=$frozen?(int)$frozen['room_minor']:$bill['room'];$label='Accommodation';$date=$frozen?substr($frozen['departed_at'],0,10):substr($b['checkin_at'],0,10);$amount=C::line($r,$booking,$type,$source,$base);$extra=null;
        }elseif($type==='extra'){
            $row=$r->run('SELECT * FROM booking_extras WHERE id=? AND booking_id=?',[$source,$booking])->fetch();if(!$row)throw new RuntimeException('Extra charge does not belong to this stay.');$quantity=R::quantity((string)$row['qty']);$price=R::minor((string)$row['unit_price']);$base=R::line($quantity,$price);if(($quantity*$price)%100!==0)$blockers[]='Historical fractional-pesewa charge needs evidenced rounding reconciliation; no source amount is guessed.';$amount=C::line($r,$booking,$type,$source,$base);$label=$row['description'];$date=substr($row['created_at'],0,10);$extra=$row['extra_id']===null?null:(int)$row['extra_id'];
        }elseif($type==='incidental'){
            $row=$r->run("SELECT * FROM stay_incidentals WHERE id=? AND booking_id=? AND status='approved'",[$source,$booking])->fetch();if(!$row)throw new RuntimeException('Choose an approved incidental from this stay.');$base=(int)$row['amount_minor'];$amount=C::line($r,$booking,$type,$source,$base);$label=$row['description'];$date=substr($row['reviewed_at']??'',0,10);$extra=null;
        }else throw new RuntimeException('Choose an actual room, extra or incidental charge.');
        $component=$type==='extra'?'extras':$type;if($amount<0||$bill[$component]<$amount)$blockers[]='Original line and final bill need evidence reconciliation; no amount is inferred.';
        if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date))$blockers[]='The original charge activity date is unknown; separate evidence review is required.';$entries=C::entries($r,$booking);$receipts=$r->run('SELECT * FROM payments WHERE booking_id=? ORDER BY id',[$booking])->fetchAll();$refunds=$r->run('SELECT * FROM stay_refunds WHERE booking_id=? ORDER BY id',[$booking])->fetchAll();$token=$this->hash([$b,$row,$bill,$entries,$receipts,$refunds,\Tivoli\Repository\ReceiptAccounting::cursor($r,$booking)]);return ['booking'=>$b,'bill'=>$bill,'charge_type'=>$type,'source_id'=>$source,'row'=>$row,'original'=>$base,'amount'=>$amount,'label'=>$label,'original_date'=>$date,'extra_id'=>$extra,'blockers'=>$blockers,'token'=>$token];
    }
    public function charges(int $actor,int $booking):array{$this->permit($actor);$r=$this->access->repo;$out=[$this->source($actor,$booking,'room',$booking)];foreach($r->run('SELECT id FROM booking_extras WHERE booking_id=? ORDER BY id',[$booking])->fetchAll(\PDO::FETCH_COLUMN) as $id)$out[]=$this->source($actor,$booking,'extra',(int)$id);foreach($r->run("SELECT id FROM stay_incidentals WHERE booking_id=? AND status='approved' ORDER BY id",[$booking])->fetchAll(\PDO::FETCH_COLUMN) as $id)$out[]=$this->source($actor,$booking,'incidental',(int)$id);return $out;}
    private function event(int $actor,string $kind,int $id,array $data,int $amount=0,string $target='guest_charge'):int{$r=$this->access->repo;$now=$this->now();$r->run('INSERT INTO finance_events(kind,target_type,target_id,amount_minor,effective_date,actor_id,payload,created_at) VALUES(?,?,?,?,?,?,?,?)',[$kind,$target,(string)$id,$amount,substr($now,0,10),$actor,json_encode($data,JSON_THROW_ON_ERROR),$now]);return (int)$r->db->lastInsertId();}
    private function active(int $booking,string $type,int $source,?int $except=null):bool{$r=$this->access->repo;$ids=$r->run("SELECT id FROM finance_events WHERE kind='gc_requested' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.booking_id'))=? AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.charge_type'))=? AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.source_id'))=?",[(string)$booking,$type,(string)$source])->fetchAll(\PDO::FETCH_COLUMN);foreach($ids as $id)if((int)$id!==$except&&!$r->run("SELECT id FROM finance_events WHERE target_type='guest_charge' AND target_id=? AND kind IN ('gc_approved','gc_rejected','gc_withdrawn') LIMIT 1",[(string)$id])->fetchColumn())return true;return false;}
    private function proposal(int $actor,array $in):array{$v=$this->source($actor,$this->id($in['booking_id']??''),$in['charge_type']??'',$this->id($in['source_id']??''));if(!hash_equals($v['token'],$in['source_token']??''))throw new RuntimeException('The charge or guest account changed. Reload the source.');if($v['blockers'])throw new RuntimeException(implode(' ',$v['blockers']));if(($in['confirmed']??'')!=='1')throw new RuntimeException('Confirm this is a supported charge correction, not a payment or stock return.');$after=R::minor(R::text($in['amount']??'',24,true));if($after>999999999999||$after===$v['amount'])throw new RuntimeException('Enter a different supported total charge.');$delta=$after-$v['amount'];return ['booking_id'=>(int)$v['booking']['id'],'charge_type'=>$v['charge_type'],'source_id'=>$v['source_id'],'extra_id'=>$v['extra_id'],'label'=>$v['label'],'before'=>$v['amount'],'after'=>$after,'delta'=>$delta,'guest_before'=>$v['bill']['balance'],'guest_after'=>$v['bill']['balance']+$delta,'source_token'=>$v['token'],'original_activity_date'=>$v['original_date'],'reason'=>R::text($in['reason']??'',2000,true)];}
    private function load(int $actor,int $id):array{
        $this->permit($actor);$r=$this->access->repo;$root=$r->run("SELECT e.*,u.name actor_name FROM finance_events e JOIN users u ON u.id=e.actor_id WHERE e.id=? AND e.kind='gc_requested' AND e.target_type='guest_charge'",[$id])->fetch();if(!$root)throw new RuntimeException('Charge correction not found.');if(!$this->owner($actor)&&(int)$root['actor_id']!==$actor)throw new PermissionDenied('Only requester and configured owner can view this private charge case.');$root['data']=json_decode($root['payload'],true,512,JSON_THROW_ON_ERROR);$history=$r->run("SELECT e.*,u.name actor_name FROM finance_events e JOIN users u ON u.id=e.actor_id WHERE e.target_type='guest_charge' AND e.target_id=? ORDER BY e.id",[(string)$id])->fetchAll();$proposal=$root['data']['proposal'];$status='pending';$revisions=[$root];$posted=null;foreach($history as &$e){$e['data']=json_decode($e['payload'],true,512,JSON_THROW_ON_ERROR);switch($e['kind']){case 'gc_revised':$proposal=$e['data']['proposal'];$revisions[]=$e;$status='pending';break;case 'gc_returned':$status='returned';break;case 'gc_rejected':$status='rejected';break;case 'gc_withdrawn':$status='withdrawn';break;case 'gc_approved':$status='posted';$posted=$e['data'];break;}}unset($e);return compact('root','history','proposal','status','revisions','posted')+['version'=>$this->hash([$id,array_column($history,'id')])];
    }
    public function detail(int $actor,int $id):array{$c=$this->load($actor,$id);$p=$c['proposal'];$c['live']=$this->source($actor,$p['booking_id'],$p['charge_type'],$p['source_id']);$c['stale']=!hash_equals($p['source_token'],$c['live']['token']);return $c;}
    public function register(int $actor,string $page='requests',int $before=0):array{$this->permit($actor);if($page==='review'&&!$this->owner($actor))throw new PermissionDenied('Owner review is restricted.');$where='';$params=[];if(!$this->owner($actor)){$where.=' AND actor_id=?';$params[]=$actor;}if($before){$where.=' AND id<?';$params[]=$before;}$ids=$this->access->repo->run("SELECT id FROM finance_events WHERE kind='gc_requested' AND target_type='guest_charge'".$where.' ORDER BY id DESC LIMIT 51',$params)->fetchAll(\PDO::FETCH_COLUMN);$more=count($ids)>50;if($more)array_pop($ids);$rows=[];foreach($ids as $id){$c=$this->detail($actor,(int)$id);if($page==='review'&&$c['status']!=='pending'||$page==='log'&&!in_array($c['status'],['posted','rejected','withdrawn'],true))continue;$rows[]=$c;}return ['rows'=>$rows,'next'=>$more?(int)end($ids):0];}
    public function attentionCount(int $actor):int{$this->permit($actor);if(!$this->owner($actor))throw new PermissionDenied('Owner review is restricted.');return (int)$this->access->repo->run("SELECT COUNT(*) FROM finance_events root WHERE root.kind='gc_requested' AND root.target_type='guest_charge' AND NOT EXISTS(SELECT 1 FROM finance_events decision WHERE decision.target_type='guest_charge' AND decision.target_id=CAST(root.id AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci AND decision.kind IN ('gc_approved','gc_rejected','gc_withdrawn'))")->fetchColumn();}
    public function execute(int $actor,string $action,array $in,string $key):array{
        try{$this->permit($actor);if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new RuntimeException('Reload the form identity.');$file=null;if(isset($in['_evidence'])){if(!in_array($action,['request','revise'],true))throw new RuntimeException('Attach evidence to request or revision.');$file=FinanceAttachment::checked($in['_evidence']);unset($in['_evidence']);}foreach($in as $v)if(!is_string($v))throw new RuntimeException('Invalid charge form.');unset($in['csrf'],$in['operation_key'],$in['action']);ksort($in);$fp=$this->hash(['guest_charge.'.$action,$in,$file?FinanceAttachment::meta($file):null]);
            return $this->access->transaction(function()use($actor,$action,$in,$key,$file,$fp){$this->permit($actor);$r=$this->access->repo;$old=$r->run('SELECT * FROM finance_operations WHERE actor_id=? AND operation_key=?',[$actor,$key])->fetch();if($old){if(!hash_equals($fp,$old['fingerprint']))throw new RuntimeException('This key belongs to different details.');$e=$r->run("SELECT id,kind,target_id FROM finance_events WHERE id=? AND target_type='guest_charge'",[$old['event_id']])->fetch();if(!$e)throw new RuntimeException('This key belongs to another workflow.');$id=$e['kind']==='gc_requested'?(int)$e['id']:(int)$e['target_id'];$this->load($actor,$id);if(in_array($action,['post','return','reject'],true)&&!$this->owner($actor))throw new PermissionDenied('Owner authority is required for replay.');return ['id'=>$id,'event_id'=>(int)$e['id'],'replayed'=>true];}
                [$id,$event]=$this->command($actor,$action,$in);if($file)FinanceAttachment::save($this->access,$actor,'guestcharge',$event,$file);$r->run('INSERT INTO finance_operations VALUES(?,?,?,?)',[$actor,$key,$fp,$event]);$this->access->audit($actor,'guest_charge.'.$action,'guest_charge',(string)$id,'succeeded',['event_id'=>$event]);return ['id'=>$id,'event_id'=>$event,'replayed'=>false];});
        }catch(\Throwable $e){$this->access->audit($actor,'guest_charge.failed','guest_charge',null,'denied',['action'=>substr($action,0,32)]);throw $e;}
    }
    private function command(int $actor,string $action,array $in):array{
        if($action==='request'){$p=$this->proposal($actor,$in);if($this->active($p['booking_id'],$p['charge_type'],$p['source_id']))throw new RuntimeException('This charge already has an unresolved correction.');$id=$this->event($actor,'gc_requested',0,array_intersect_key($p,array_flip(['booking_id','charge_type','source_id']))+['proposal'=>$p]);return [$id,$id];}
        $id=$this->id($in['id']??'');$c=$this->load($actor,$id);if(!hash_equals($c['version'],$in['version']??''))throw new RuntimeException('The case changed. Reload its latest version.');$p=$c['proposal'];
        if($action==='revise'){if((int)$c['root']['actor_id']!==$actor||$c['status']!=='returned')throw new PermissionDenied('Only requester may revise a returned case.');if(($in['booking_id']??'')!==(string)$p['booking_id']||($in['charge_type']??'')!==$p['charge_type']||($in['source_id']??'')!==(string)$p['source_id'])throw new RuntimeException('A revision must retain the original charge source.');$p=$this->proposal($actor,$in);return [$id,$this->event($actor,'gc_revised',$id,['proposal'=>$p])];}
        if($action==='withdraw'){if((int)$c['root']['actor_id']!==$actor||!in_array($c['status'],['pending','returned'],true))throw new PermissionDenied('Only requester may withdraw an unposted case.');return [$id,$this->event($actor,'gc_withdrawn',$id,[])];}
        if(!$this->owner($actor))throw new PermissionDenied('Only the configured owner may decide charge corrections.');if($c['status']!=='pending')throw new RuntimeException('Only pending requests may be decided.');$reason=R::text($in['reason']??'',2000,true);
        if(in_array($action,['return','reject'],true))return [$id,$this->event($actor,$action==='return'?'gc_returned':'gc_rejected',$id,['reason'=>$reason])];
        if($action!=='post')throw new RuntimeException('Unknown charge action.');if(($in['verified']??'')!=='1')throw new RuntimeException('Independently verify the charge and all effects.');$v=$this->source($actor,$p['booking_id'],$p['charge_type'],$p['source_id']);if($v['blockers']||!hash_equals($p['source_token'],$v['token']))throw new RuntimeException('The charge or guest account changed or is unsupported. Return for revision.');FinanceService::guardSource($this->access,substr($this->now(),0,10));$data=array_intersect_key($p,array_flip(['booking_id','charge_type','source_id','extra_id','label','before','after','delta','original_activity_date']))+['request_id'=>$id,'actual_money_moved'=>0];$posted=$this->event($actor,'gc_posted',$p['booking_id'],$data,$p['delta'],'booking');return [$id,$this->event($actor,'gc_approved',$id,['posted_id'=>$posted,'reason'=>$reason])];
    }
}
